it('sums the usage of every round that reported one and omits rounds that reported none', async () => {
  let seen: UsageMetadata | undefined;
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_session, _text, reported) => {
      seen = reported;
    },
  };
  const orchestrator = createChatOrchestrator(
    scriptedProvider([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
      [TOOL_CALL, STOP_FOR_TOOL],
      [
        {type: 'text', text: 'done'},
        {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 30, outputTokens: 8, totalTokens: 38}},
      ],
    ]),
    promptBuilder,
    registryReturning({result: 'r'}),
    {hooks}
  );

  await orchestrator.processMessage(createSession('ask'));

  expect(seen).toEqual({inputTokens: 40, outputTokens: 10, totalTokens: 50});
});

