it('sums the usage of every round that reported one and omits rounds that reported none', async () => {
  const firstRound: MessageChunk[] = [
    TOOL_CALL,
    {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}},
  ];
  const unreportedRound: MessageChunk[] = [TOOL_CALL, STOP_FOR_TOOL];
  const finalRound: MessageChunk[] = [
    {type: 'text', text: 'done'},
    {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 30, outputTokens: 8, totalTokens: 38}},
  ];
  const reports: Array<UsageMetadata | undefined> = [];
  const afterModelResponse: OrchestratorHooks['afterModelResponse'] = async (_session, _text, turnUsage) =>
    void reports.push(turnUsage);

  await createChatOrchestrator(
    scriptedProvider([firstRound, unreportedRound, finalRound]),
    promptBuilder,
    registryReturning({result: 'r'}),
    {hooks: {afterModelResponse}}
  ).processMessage(createSession('ask'));

  expect(reports).toEqual([{inputTokens: 40, outputTokens: 10, totalTokens: 50}]);
});
